#!/usr/bin/env python3
"""Generate terminal adapters and the guide from the editor's shared keymap."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def artifacts():
    bindings = json.loads((ROOT / 'config/keymap.json').read_text())
    for field in ('id', 'key', 'terminal'):
        values = [item[field] for item in bindings]
        if len(set(values)) != len(values):
            raise ValueError('Duplicate binding ' + field)
    ghostty = ['# Jetvim: use in a dedicated terminal window, not your global configuration.',
               '# Generated by python3 scripts/generate.py from config/keymap.json.',
               '# Example: ghostty --config-file=/absolute/path/to/terminal/ghostty.conf',
               '# Then run ./jetvim in that window.', '']
    guide = ['# Jetvim shortcuts', '',
             'macOS JetBrains bindings. Available in typing, selection, and Vim normal mode.', '',
             'Terminal interception can prevent any application from receiving a shortcut.',
             'Warp: see `terminal/warp.md`; other terminal adapters live in `terminal/`.', '',
             'Escape enters Vim mode. Fallbacks are typed in normal mode: press Escape,',
             'then Space followed by the displayed key. `Space Space` searches files and actions.', '',
             '| Action | macOS shortcut | Normal-mode fallback | iTerm2: Send Escape Sequence |',
             '| --- | --- | --- | --- |']
    iterm = {}
    special = {'enter': 0xD, 'backspace': 0x7F, 'delete': 0xF728, 'space': 0x20,
               'left': 0xF702, 'right': 0xF703, 'up': 0xF700, 'down': 0xF701,
               'escape': 0x1B, 'bracket_left': ord('['), 'bracket_right': ord(']'),
               'comma': ord(','), 'slash': ord('/'), 'equal': ord('='), 'minus': ord('-')}
    masks = {'super': 0x100000, 'shift': 0x20000, 'alt': 0x80000, 'ctrl': 0x40000}
    shifted = {'/': '?', '=': '+', '-': '_', '[': '{', ']': '}'}
    shortcuts = [(index, item) for index, item in enumerate(bindings, 1)]
    shortcuts += [(index, dict(item, **alias)) for index, item in enumerate(bindings, 1) for alias in item.get('aliases', [])]
    for field in ('key', 'terminal'):
        values = [item[field] for _, item in shortcuts]
        if len(set(values)) != len(values):
            raise ValueError('Duplicate shortcut or alias ' + field)
    for index, item in shortcuts:
        sequence = f'[{0xF0000 + index}u'
        ghostty += [f'# {item["label"]} — {item["shortcut"]}', f'keybind = {item["terminal"]}=esc:{sequence}']
        fallback = item.get('fallback', '—').replace('<leader>', 'Space ').replace('<', '&lt;').replace('>', '&gt;')
        guide.append(f'| {item["label"]} | {item["shortcut"]} | {fallback} | `{sequence}` |')
        parts = item['terminal'].split('+')
        key = parts[-1]
        code = special.get(key)
        if code is None:
            code = 0xF704 + int(key[1:]) - 1 if key.startswith('f') and key[1:].isdigit() else ord(key)
        if 'shift' in parts:
            char = chr(code)
            code = ord(shifted.get(char, char.upper()))
        mask = sum(masks[part] for part in parts[:-1])
        # Arrow/function keys include NSEventModifierFlagNumericPad in iTerm2.
        if code >= 0xF700:
            mask |= 0x200000
        iterm[f'0x{code:x}-0x{mask:x}'] = {'Action': 10, 'Text': sequence}
    guide += ['', 'Double Shift is available with the optional Warp bridge. Else use ⌘⇧P or Space Space.',
              'Search Everywhere currently searches project files and actions.',
              'Language-aware navigation, completion and refactoring require an enabled LSP server.',
              '⌥↑ expands through installed syntax nodes or enclosing code-block boundaries; ⌥↓ reverses each step.',
              'The parserless fallback handles delimiters, strings/comments, Lua blocks and Python/YAML indentation;',
              'ambiguous language constructs may differ from JetBrains semantic selection.',
              'Project sidebar: type to search visible entries; arrows move through matches, Backspace edits,',
              'Escape clears the query before returning to the editor. Plain letter keys are search text.',
              'Left collapses a folder or selects its parent; Right expands it or enters its first child.',
              'The project root is selectable. Drag the sidebar divider to resize it.',
              '⌘N or Insert in the project tree creates a file; a trailing / creates a directory.',
              'Creation uses the selected directory or the selected file’s parent; ⌘N is tree-only.',
              '⌘Delete (the Backspace key on Mac) in the tree confirms permanent file/folder deletion;',
              'native ⌘Forward Delete also works there. Save/discard dirty files and finish save hooks first.',
              'In an editor, ⌘Backspace continues to delete the current line.',
              'Shift+F6 in the tree renames the selected file/folder in place and keeps open edits.',
              'In an editor, Shift+F6 still renames a symbol through the language server.',
              'Ctrl+Option+Arrow resizes the focused pane by moving its shared divider in that direction.',
              'For a left sidebar, Right grows and Left shrinks; for a bottom pane, Up grows and Down shrinks.',
              'Resize steps are four columns or two rows; dimensions stop at ten columns or three rows.',
              'Git Changes (⌘9): arrows select, Enter opens, Tab focuses the diff, R refreshes,',
              'Escape focuses the editor and Shift-Escape hides the tool window. Diffs are read-only.',
              'These are implemented bindings, not a claim of complete IntelliJ feature parity.', '']
    return {
        ROOT / 'terminal/ghostty.conf': '\n'.join(ghostty) + '\n',
        ROOT / 'terminal/Jetvim.itermkeymap': json.dumps({'Key Mappings': iterm, 'Touch Bar Items': []}, indent=2) + '\n',
        ROOT / 'docs/shortcuts.md': '\n'.join(guide),
    }


if __name__ == '__main__':
    import sys
    check = '--check' in sys.argv
    failed = []
    for path, content in artifacts().items():
        if check:
            if not path.exists() or path.read_text() != content:
                failed.append(str(path.relative_to(ROOT)))
        else:
            path.write_text(content)
    if failed:
        raise SystemExit('Regenerate terminal adapters: ' + ', '.join(failed))
    print('Terminal adapters and shortcut guide are up to date.' if check else 'Generated terminal adapters and shortcut guide.')
